{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "In humans, the closest analogue SCH 23390 showed rapid transfer into brain by PET with 1.2-1.5% of injected radioactivity in brain at 4.5 min, directly demonstrating meaningful CNS access for the same benzazepine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "An iodo-substituted close analogue showed good initial rat brain uptake (1.59% dose/organ at 2 min after IV), supporting CNS penetration for analogues with bulky aromatic substituents on the benzazepine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The 4-iodophenyl analogue showed good rat brain uptake (2.27% dose/whole brain at 2 min), confirming that replacing the phenyl group with substituted aryl groups does not abolish BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "In humans, 123I-SCH 23982 showed brain uptake within 10 min by SPECT, including striatal uptake, supporting CNS access for this benzazepine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A des-chloro analogue had a brain-to-blood ratio of about 1.2 at 10 min in rats, indicating active brain uptake and supporting class-level CNS penetration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close structural analogue of SCH 23390 and related 3-benzazepines that consistently show rapid, meaningful brain uptake in humans, monkeys, and rats across PET, SPECT, and biodistribution studies. The lipophilic dihydrobenzofuran substituent is unlikely to disrupt the established CNS penetration of this scaffold.",
  "evidence_gaps": [
    "No direct experimental measurement for the exact query molecule.",
    "No explicit efflux-transporter data for the query, though close analogues with similar lipophilic aryl substituents still penetrate well."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

